        using(var source=new Bitmap(80,60,PixelFormat.Format32bppArgb))using(var target=new Bitmap(80,60,PixelFormat.Format32bppArgb)){for(int y=0;y<60;y++)for(int x=0;x<80;x++)source.SetPixel(x,y,Color.FromArgb((x*13+y*7)%256,(x*3)%256,(y*5)%256,(x+y)%256));Art.CopyPixelRegion(source,target,new Rectangle(7,9,50,30));bool exact=true;for(int y=0;y<60;y++)for(int x=0;x<80;x++)if(target.GetPixel(x,y).ToArgb()!=(new Rectangle(7,9,50,30).Contains(x,y)?source.GetPixel(x,y).ToArgb():0))exact=false;check(exact,"Dirty-region copying preserves exact color and alpha without touching other pixels");}
        Art.ClearLayerImageCache();var mark=new Mark {Kind="Image",X=0,Y=0,W=80,H=60};using(var red=Blank(80,60)){using(var graphics=Graphics.FromImage(red))graphics.Clear(Color.Red);mark.Image=Art.Bytes(red);}int decodes=Art.LayerImageDecodes;using(var background=Blank(80,60))using(var first=Art.Render(background,new List<Mark>{mark}))using(var next=Art.Render(background,new List<Mark>{mark})){check(Art.LayerImageDecodes==decodes+1&&Art.Bytes(first).SequenceEqual(Art.Bytes(next)),"Repeated image draws decode once and preserve identical pixels");using(var green=Blank(80,60)){using(var graphics=Graphics.FromImage(green))graphics.Clear(Color.Lime);mark.Image=Art.Bytes(green);}using(var changed=Art.Render(background,new List<Mark>{mark}))check(changed.GetPixel(20,20).ToArgb()==Color.Lime.ToArgb()&&Art.LayerImageDecodes==decodes+2,"Replacing image bytes invalidates decoded image reuse");}check(Art.LayerImageCacheBytes<=40L*1024*1024,"Decoded image reuse has a fixed memory budget");Art.ClearLayerImageCache();
        LoadBitmap(new Bitmap(1200,800,PixelFormat.Format32bppArgb),"Preview quality comparison");using(var graphics=Graphics.FromImage(Background)){using(var brush=new SolidBrush(Color.FromArgb(70,255,40,80)))graphics.FillEllipse(brush,40,50,700,500);using(var font=new Font("Segoe UI",28,FontStyle.Regular,GraphicsUnit.Pixel))graphics.DrawString("Quality stays identical",font,Brushes.Navy,120,160);}RefreshImage();SetTool("Crop");Crop=new RectangleF(100,80,950,600);Show();Application.DoEvents();View.FinishZoomGesture();
        foreach(float zoom in new[]{.55f,1f,2.4f}){View.Zoom=zoom;View.PanX=17.25f;View.PanY=-23.5f;using(var direct=new Bitmap(View.Width,View.Height))using(var cached=new Bitmap(View.Width,View.Height)){View.DisableStableRasterForTests=true;View.DrawToBitmap(direct,new Rectangle(Point.Empty,direct.Size));View.DisableStableRasterForTests=false;View.DrawToBitmap(cached,new Rectangle(Point.Empty,cached.Size));check(Art.Bytes(direct).SequenceEqual(Art.Bytes(cached)),"Cached crop preview matches original drawing pixel for pixel at "+zoom+"x");int builds=View.StableRasterBuilds;Crop=new RectangleF(120,90,920,570);View.DrawToBitmap(cached,new Rectangle(Point.Empty,cached.Size));check(View.StableRasterBuilds==builds,"Moving crop handles reuses the unchanged full-quality image at "+zoom+"x");}}
        View.DisableStableRasterForTests=false;Hide();LoadBitmap(Blank(100,100),"Test");
    }
