        Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};var timings=new List<string>();
        LoadBitmap(Blank(3840,2160),"Crop performance");using(var graphics=Graphics.FromImage(Background))using(var font=new Font("Segoe UI",32,FontStyle.Regular,GraphicsUnit.Pixel)){graphics.Clear(Color.White);for(int y=60;y<2100;y+=140)graphics.DrawString("Image details and text stay unchanged",font,Brushes.Navy,60,y);using(var brush=new SolidBrush(Color.FromArgb(90,20,150,250)))graphics.FillEllipse(brush,900,500,1300,900);}RefreshImage();SetTool("Crop");Show();Application.DoEvents();
        using(var frame=new Bitmap(View.Width,View.Height))foreach(float zoom in new[]{.55f,2.4f}){View.Zoom=zoom;View.PanX=View.PanY=0;Crop=new RectangleF(100,100,3200,1800);View.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));var preview=Preview;int history=undo.Count;BeginCropGesture(new PointF(Crop.Value.Right,Crop.Value.Top+900));var clock=Stopwatch.StartNew();for(int i=0;i<8;i++){HandleCropMove(new PointF(3290-i*5,1000));View.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));}clock.Stop();timings.Add("Crop handles at "+zoom+"x: "+(clock.Elapsed.TotalMilliseconds/8).ToString("F2")+" ms/frame");EndCropGesture();check(Object.ReferenceEquals(preview,Preview)&&undo.Count==history,"Crop handle movement preserves image pixels and history at "+zoom+"x");frame.Save(Path.Combine(folder,"crop-quality-"+zoom.ToString(System.Globalization.CultureInfo.InvariantCulture)+".png"));}
