        SetTool("Pen");View.Zoom=1;View.PanX=View.PanY=0;var origin=View.Origin;var down=new MouseEventArgs(MouseButtons.Left,1,(int)origin.X+500,(int)origin.Y+500,0);CanvasDownWithModifiers(down,Keys.Control);stopwatch.Restart();for(int i=0;i<1500;i++)CanvasMove(new MouseEventArgs(MouseButtons.Left,0,(int)origin.X+500+i%900,(int)origin.Y+500+(i*7)%700,0));stopwatch.Stop();timings.Add("1500 pen input points: "+stopwatch.Elapsed.TotalMilliseconds.ToString("F2")+" ms");if(draft!=null){float left=draft.Points.Min(point=>point.X),top=draft.Points.Min(point=>point.Y),right=draft.Points.Max(point=>point.X),bottom=draft.Points.Max(point=>point.Y);check(draft.X==left&&draft.Y==top&&draft.W==Math.Max(1,right-left)&&draft.H==Math.Max(1,bottom-top),"Pen bounds match the complete input-point set");}CancelDrag();report.AddRange(timings);File.WriteAllLines(Path.Combine(folder,"performance-audit.txt"),new[]{"Synthetic 4K inputs; off-screen rendering and UI-thread work, not physical display latency."}.Concat(timings));Hide();LoadBitmap(Blank(100,100),"Test");
    }
